//! Grade ladder — straight-A only (≥95%) per band AND per domain.
//!
//! Loads open curriculum bank.tsv when present (math tables, Dolch, phonics,
//! science) generated by `python run_curriculum_open.py`.
//! Falls back to embedded seed if bank missing.
//!
//! Domains: math | science | literacy | vision
//! Vision = tutor-ablated digit identity on Fixed lattice (train/test).

const std = @import("std");
const fixed = @import("fixed.zig");
const memory_f = @import("memory_fixed.zig");
const teach_f = @import("teach_fixed.zig");
const lexicon_en = @import("lexicon_en_fixed.zig");
const organism_f = @import("organism_fixed.zig");
const brain_f = @import("brain_fixed.zig");
const Fixed = fixed.Fixed;

pub const PASS_THRESHOLD: f64 = 0.95;

pub const GradeBand = enum(u8) {
    preschool = 0,
    kindergarten = 1,
    grade1 = 2,
};

pub const Domain = enum(u8) {
    math = 0,
    science = 1,
    literacy = 2,
    vision = 3,
    other = 4,
};

pub fn bandName(b: GradeBand) []const u8 {
    return switch (b) {
        .preschool => "preschool",
        .kindergarten => "kindergarten",
        .grade1 => "grade1",
    };
}

pub fn domainName(d: Domain) []const u8 {
    return switch (d) {
        .math => "math",
        .science => "science",
        .literacy => "literacy",
        .vision => "vision",
        .other => "other",
    };
}

fn parseBand(s: []const u8) ?GradeBand {
    if (std.mem.eql(u8, s, "preschool") or std.mem.eql(u8, s, "pk")) return .preschool;
    if (std.mem.eql(u8, s, "kindergarten") or std.mem.eql(u8, s, "k") or std.mem.eql(u8, s, "kinder")) return .kindergarten;
    if (std.mem.eql(u8, s, "grade1") or std.mem.eql(u8, s, "g1") or std.mem.eql(u8, s, "first")) return .grade1;
    return null;
}

fn parseDomain(s: []const u8) Domain {
    if (std.mem.eql(u8, s, "math")) return .math;
    if (std.mem.eql(u8, s, "science") or std.mem.eql(u8, s, "life") or std.mem.eql(u8, s, "body") or std.mem.eql(u8, s, "health") or std.mem.eql(u8, s, "safety") or std.mem.eql(u8, s, "time") or std.mem.eql(u8, s, "geo") or std.mem.eql(u8, s, "social")) return .science;
    if (std.mem.eql(u8, s, "literacy") or std.mem.eql(u8, s, "reading") or std.mem.eql(u8, s, "writing")) return .literacy;
    if (std.mem.eql(u8, s, "vision") or std.mem.eql(u8, s, "image") or std.mem.eql(u8, s, "digit")) return .vision;
    return .other;
}

// ---------- embedded seed (fallback if bank.tsv absent) ----------
